export default function f({ content, filename }) {
  if (
    !filename.toLowerCase().endsWith(".pdf") ||
    typeof content !== "string" ||
    !content.startsWith("JVBERi0")
  )
    throw Error("Expected a nonempty PDF attachment");
  return { fileContent: content, fileName: filename };
}

