export default function f({ text, errors, status }) {
  if (status && status !== "Success")
    throw Error("Encodian PDF extraction failed: " + (errors?.[0] || status));
  if (typeof text !== "string" || !text.trim()) throw Error("PDF has no extractable text");
  if (text.length > 15800) throw Error("Extracted PDF text exceeds 15,800 characters");
  return { text: text.trim() };
}

