export default async function f({ messageId, filename, link, invoice, spreadsheetId, range }, ctx) {
  if (!spreadsheetId || spreadsheetId.includes("YOUR_SPREADSHEET_ID"))
    throw Error("Configure spreadsheetId");
  const key = "invoice:" + messageId + ":" + filename;
  const existing = await ctx.state.get(key);
  if (existing?.status === "done") return { key, write: false, spreadsheetId, range, values: [] };
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    write: true,
    spreadsheetId,
    range,
    values: [[String(invoice?.date || ""), filename, String(invoice?.total || ""), link]],
  };
}

