export default async function f({ key, updatedRows, messageId }, ctx) {
  if (!updatedRows || updatedRows < 1) throw Error("Spreadsheet append did not confirm a row");
  await ctx.state.set(key, { status: "done" });
  return { messageIds: [messageId] };
}
